output_text:
[
  {
    "id": "cart_free_single_file_shelf_aisles",
    "text": "Carts must not be taken into single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFilePassage": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "shelvesOnBothSides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "singleFilePassage",
            "shelvesOnBothSides"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    },
    "justification": "The rule is defined by aisle width and shelf adjacency, so it applies to any store layout with narrow shelf aisles rather than to particular coordinates."
  },
  {
    "id": "no_cart_entry_into_single_file_shelf_aisle",
    "text": "A shopper must not enter a single-file shelf aisle while still holding a cart.",
    "abstraction": {
      "state_properties": {
        "singleFilePassage": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "shelvesOnBothSides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "singleFilePassage",
            "shelvesOnBothSides"
          ]
        }
      },
      "events": {
        "enterSingleFileShelfAisleWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": {
            "and": [
              "hasCart",
              "singleFileShelfAisle"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileShelfAisleWithCart"
    },
    "justification": "The prohibited transition is described in terms of moving into a narrow shelf-flanked passage, which is a layout-independent spatial relation."
  },
  {
    "id": "push_carts_only_where_aisle_is_wide_enough",
    "text": "Carts may only be pushed through aisles that are wide enough for carts.",
    "abstraction": {
      "state_properties": {
        "aisleWideEnoughForCart": {
          "ge": [
            "freeWidthH",
            2
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "MOVE",
          {
            "not": "aisleWideEnoughForCart"
          }
        ]
      }
    },
    "justification": "The constraint depends on local free-space width rather than named cells, so the same norm can be evaluated in stores with different floor plans."
  },
  {
    "id": "park_carts_only_in_wide_circulation_space",
    "text": "If a shopper temporarily leaves a cart, the cart should be left in a wide circulation area away from shelves.",
    "abstraction": {
      "state_properties": {
        "wideCirculationArea": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                3
              ]
            },
            {
              "ge": [
                "freeWidthV",
                3
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "cartDropped": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartDropped",
          {
            "not": "wideCirculationArea"
          }
        ]
      }
    },
    "justification": "The allowed parking location is characterized by usable open space and lack of shelf adjacency, not by a specific parking coordinate."
  },
  {
    "id": "no_cart_shelf_selection_in_single_file_aisle",
    "text": "A shopper must not select or interact with shelf goods in a single-file shelf aisle while holding a cart.",
    "abstraction": {
      "state_properties": {
        "singleFilePassage": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "shelvesOnBothSides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "singleFilePassage",
            "shelvesOnBothSides"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "INTERACT",
          "singleFileShelfAisle"
        ]
      }
    },
    "justification": "The rule concerns the general situation of handling goods in a narrow shelf aisle, independent of where that aisle is located."
  },
  {
    "id": "reclaim_cart_after_on_foot_single_file_selection",
    "text": "After selecting an item on foot inside a single-file shelf aisle, the shopper must reclaim their cart before leaving the store.",
    "abstraction": {
      "state_properties": {
        "singleFilePassage": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "shelvesOnBothSides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "singleFilePassage",
            "shelvesOnBothSides"
          ]
        }
      },
      "events": {
        "itemSelectedOnFootInSingleFileAisle": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT",
              "singleFileShelfAisle"
            ]
          },
          "post": null
        },
        "cartReclaimed": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "itemSelectedOnFootInSingleFileAisle",
      "discharge": "cartReclaimed"
    },
    "justification": "The obligation is triggered by a layout-independent activity pattern—leaving the cart to shop in a narrow shelf aisle—rather than by visiting a named cell."
  },
  {
    "id": "must_get_cart_for_shopping_trip",
    "text": "A shopper should obtain a cart during the shopping trip before exiting.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "hasCart"
    },
    "justification": "Cart possession is a general shopping-domain condition and does not depend on the position or geometry of any particular store."
  },
  {
    "id": "no_exit_without_cart",
    "text": "A shopper must not leave the store without their cart.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    },
    "justification": "The exit rule refers only to the general act of leaving with or without a cart, so it remains meaningful across different store layouts."
  }
]
